"""Dependency-free HTML for the local evaluation workspace."""


def evaluation_page() -> str:
    return r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Crate Digger Evaluation Room</title>
<style>
:root{--ink:#201d18;--muted:#716b61;--paper:#f4f0e7;--card:#fffdf8;--line:#d8d0c2;--accent:#b7472a;--accent2:#163d38;--soft:#e8e0d1;--ease:cubic-bezier(.23,1,.32,1)}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 Inter,ui-sans-serif,system-ui,sans-serif}
button,input,textarea,select{font:inherit}button{cursor:pointer}.shell{max-width:1120px;margin:auto;padding:32px 24px 72px}
header{display:flex;align-items:end;justify-content:space-between;gap:24px;margin-bottom:28px}.eyebrow{font-size:12px;font-weight:750;letter-spacing:.12em;text-transform:uppercase;color:var(--accent)}
h1{font:600 clamp(32px,5vw,58px)/.98 Georgia,serif;letter-spacing:-.035em;margin:7px 0 8px;max-width:700px}h2,h3{margin:0}p{color:var(--muted)}
.status{min-width:180px;text-align:right}.meter{height:7px;background:var(--soft);border-radius:99px;overflow:hidden}.meter>i{display:block;height:100%;background:var(--accent2);transition:width 220ms var(--ease)}
.tabs{display:flex;gap:6px;border-bottom:1px solid var(--line);margin-bottom:24px}.tab{border:0;background:transparent;padding:10px 14px;color:var(--muted);font-weight:650;border-bottom:2px solid transparent}.tab[aria-selected=true]{color:var(--ink);border-color:var(--accent)}
.panel[hidden]{display:none}.grid{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(280px,.75fr);gap:22px}.card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:22px;box-shadow:0 1px 0 rgba(38,31,22,.04)}
.field{margin:0 0 16px}.field label{display:block;font-size:13px;font-weight:720;margin-bottom:6px}.hint{font-size:12px;color:var(--muted);font-weight:450}.row{display:grid;grid-template-columns:1fr 1fr;gap:14px}
input,textarea,select{width:100%;border:1px solid var(--line);border-radius:9px;background:#fff;padding:10px 11px;color:var(--ink);outline:none;transition:border-color 150ms ease,box-shadow 150ms ease}textarea{min-height:118px;resize:vertical}input:focus,textarea:focus,select:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(183,71,42,.12)}
.actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.btn{border:1px solid var(--line);border-radius:9px;padding:10px 14px;background:var(--card);color:var(--ink);font-weight:720;transition:transform 140ms var(--ease),background-color 150ms ease}.btn.primary{background:var(--accent2);border-color:var(--accent2);color:white}.btn.danger{background:var(--accent);border-color:var(--accent);color:white}.btn:active{transform:scale(.97)}.btn:disabled{opacity:.45;cursor:not-allowed}
.brief-list{display:grid;gap:8px;max-height:610px;overflow:auto}.brief-item{border:1px solid var(--line);border-radius:10px;padding:11px 12px;background:#fff}.brief-item strong{display:block;font-size:13px}.brief-item span{display:block;color:var(--muted);font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.empty{padding:34px 16px;text-align:center;border:1px dashed var(--line);border-radius:10px;color:var(--muted)}.notice{padding:11px 13px;border-radius:9px;background:#efe8d9;color:#594f41;font-size:13px}.notice.ok{background:#e0ebe5;color:#244b3d}.notice.bad{background:#f5ded7;color:#742f1f}
.evaluation-head{display:grid;grid-template-columns:240px 1fr auto;gap:12px;align-items:end;margin-bottom:18px}.prompt{background:var(--accent2);color:#fff;border-radius:14px;padding:22px;margin-bottom:18px}.prompt p{color:#dbe8e4;margin-bottom:0}.recommendations{display:grid;gap:16px}.rec{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:20px}.rec-title{display:flex;justify-content:space-between;gap:12px}.rec-title h3{font:600 23px/1.15 Georgia,serif}.chips{display:flex;gap:6px;flex-wrap:wrap;margin:12px 0}.chip{font-size:12px;background:var(--soft);border-radius:99px;padding:4px 8px;color:#514a40}
.ratings{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-top:18px}.rating label{display:block;font-size:12px;font-weight:700;min-height:36px}.scale{display:grid;grid-template-columns:repeat(5,1fr);border:1px solid var(--line);border-radius:8px;overflow:hidden}.scale input{position:absolute;opacity:0;pointer-events:none}.scale span{display:grid;place-items:center;height:34px;background:#fff;border-right:1px solid var(--line);cursor:pointer}.scale label:last-child span{border:0}.scale input:checked+span{background:var(--accent);color:white}.why{margin-top:14px}.why textarea{min-height:80px}.saved{color:var(--accent2);font-size:13px;font-weight:700}
@media(max-width:800px){header{align-items:start;flex-direction:column}.status{text-align:left;width:100%}.grid,.evaluation-head{grid-template-columns:1fr}.ratings{grid-template-columns:1fr 1fr}.row{grid-template-columns:1fr}}
@media(max-width:480px){.shell{padding:22px 14px 56px}.ratings{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition-duration:.01ms!important}}
</style></head>
<body><main class="shell">
<header><div><div class="eyebrow">Crate Digger Research</div><h1>Evaluation Room</h1><p>Collect clean prompts. Listen carefully. Explain the judgment.</p></div><div class="status"><strong id="count">0 of 25 briefs</strong><div class="meter"><i id="progress" style="width:0"></i></div><small id="freezeState">Draft collection</small></div></header>
<nav class="tabs" aria-label="Evaluation stages"><button class="tab" data-tab="briefs" aria-selected="true">1. Brief studio</button><button class="tab" data-tab="listen" aria-selected="false">2. Listening room</button></nav>
<section class="panel" id="briefsPanel"><div class="grid"><form class="card" id="briefForm"><h2>Add an unseen brief</h2><p>Use a new request. Do not include the albums you expect back.</p>
<div class="field"><label for="brief">Recommendation request</label><textarea id="brief" required placeholder="Find music connected to an album or quality, and explain what matters to you."></textarea></div>
<div class="row"><div class="field"><label for="seedArtist">Seed artist <span class="hint">optional</span></label><input id="seedArtist"></div><div class="field"><label for="seedAlbum">Seed album <span class="hint">optional</span></label><input id="seedAlbum"></div></div>
<div class="field"><label for="quality">Quality to preserve or explore</label><input id="quality" placeholder="For example: density, sacred solitude, uneasy warmth"></div>
<div class="row"><div class="field"><label for="depth">Discovery depth</label><select id="depth"><option value="">Let the engine ask</option><option value="1">1, familiar</option><option value="2">2, adjacent</option><option value="3">3, exploratory</option><option value="4">4, deep</option><option value="5">5, frontier</option></select></div><div class="field"><label for="visibility">Visibility</label><select id="visibility"><option value="">Let the engine ask</option><option>any</option><option>familiar</option><option>mixed</option><option>underheard</option></select></div></div>
<div class="row"><div class="field"><label for="exclusions">Exclusions <span class="hint">optional</span></label><input id="exclusions" placeholder="Artists, eras, or qualities to avoid"></div><div class="field"><label for="visualRole">Visual role</label><select id="visualRole"><option value="">No image</option><option value="preserve">Preserve</option><option value="transform">Transform</option><option value="journey">Journey</option></select></div></div>
<div class="field"><label for="contributor">Your name or evaluator code</label><input id="contributor" required></div><div class="actions"><button class="btn primary" type="submit">Save brief</button><span id="briefMessage"></span></div></form>
<aside class="card"><h2>Holdout set</h2><p id="setHelp">Collect exactly 25, review them, then freeze the set.</p><div class="brief-list" id="briefList"></div><div class="actions" style="margin-top:16px"><button class="btn danger" id="freeze" type="button" disabled>Freeze 25 briefs</button></div></aside></div></section>
<section class="panel" id="listenPanel" hidden><div class="evaluation-head"><div class="field"><label for="evaluator">Evaluator name or code</label><input id="evaluator" placeholder="Required before listening"></div><div class="field"><label for="caseSelect">Brief</label><select id="caseSelect"></select></div><button class="btn primary" id="generate">Get recommendation set</button></div><div id="listenNotice" class="notice">The set must be frozen before evaluation begins.</div><div id="prompt"></div><div class="recommendations" id="recommendations"></div></section>
</main>
<script>
const $=id=>document.getElementById(id);let state={briefs:[],frozen:false};let currentResults=[];
document.querySelectorAll('.tab').forEach(tab=>tab.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(x=>x.setAttribute('aria-selected',x===tab));$('briefsPanel').hidden=tab.dataset.tab!=='briefs';$('listenPanel').hidden=tab.dataset.tab!=='listen';}));
async function api(url,options={}){const r=await fetch(url,{headers:{'Content-Type':'application/json'},...options});const data=await r.json();if(!r.ok||data.error)throw new Error(data.detail||data.error||'Request failed');return data}
async function refresh(){const evaluator=$('evaluator').value.trim();state=await api('/evaluation/state?evaluator_id='+encodeURIComponent(evaluator));$('count').textContent=`${state.brief_count} of ${state.target_count} briefs`;$('progress').style.width=`${Math.min(100,state.brief_count/state.target_count*100)}%`;$('freezeState').textContent=state.frozen?'Frozen holdout':'Draft collection';$('briefForm').querySelectorAll('input,textarea,select,button').forEach(x=>x.disabled=state.frozen);$('freeze').disabled=state.frozen||state.brief_count!==25;renderBriefs();renderCases()}
function renderBriefs(){$('briefList').innerHTML=state.briefs.length?state.briefs.map((b,i)=>`<div class="brief-item"><strong>${i+1}. ${escapeHtml(b.seed_album||b.liked_quality||'Open prompt')}</strong><span>${escapeHtml(b.brief)}</span></div>`).join(''):'<div class="empty">No briefs yet</div>'}
function renderCases(){$('caseSelect').innerHTML='<option value="">Choose a brief</option>'+state.briefs.map((b,i)=>`<option value="${escapeHtml(b.id)}">${state.completed_case_ids.includes(b.id)?'✓ ':''}${i+1}. ${escapeHtml(b.seed_album||b.liked_quality||b.brief.slice(0,50))}</option>`).join('');$('listenNotice').textContent=state.frozen?'Evaluate one brief at a time. Feedback is saved per recommendation.':'The set must be frozen before evaluation begins.';$('listenNotice').className='notice '+(state.frozen?'ok':'')}
$('briefForm').addEventListener('submit',async e=>{e.preventDefault();const body={brief:$('brief').value,seed_artist:$('seedArtist').value,seed_album:$('seedAlbum').value,liked_quality:$('quality').value,discovery_depth:$('depth').value,visibility:$('visibility').value,exclusions:$('exclusions').value,visual_role:$('visualRole').value,submitted_by:$('contributor').value};try{await api('/evaluation/briefs',{method:'POST',body:JSON.stringify(body)});$('brief').value='';$('seedArtist').value='';$('seedAlbum').value='';$('quality').value='';$('exclusions').value='';$('briefMessage').textContent='Saved';$('briefMessage').className='saved';await refresh()}catch(err){$('briefMessage').textContent=err.message;$('briefMessage').className='notice bad'}});
$('freeze').addEventListener('click',async()=>{if(!confirm('Freeze all 25 briefs? They cannot be edited after this.'))return;try{await api('/evaluation/freeze',{method:'POST'});await refresh()}catch(err){alert(err.message)}});
$('generate').addEventListener('click',async()=>{const evaluator=$('evaluator').value.trim(),id=$('caseSelect').value;if(!state.frozen)return alert('Freeze the holdout first.');if(!evaluator||!id)return alert('Choose an evaluator code and brief.');const c=state.briefs.find(x=>x.id===id);const combined=[c.brief,c.seed_album?`Seed album: ${c.seed_album}`:'',c.liked_quality?`Priority quality: ${c.liked_quality}`:'',c.exclusions?`Avoid: ${c.exclusions}`:''].filter(Boolean).join('\n');$('prompt').innerHTML=`<div class="prompt"><div class="eyebrow" style="color:#dfb49f">Frozen brief</div><h2>${escapeHtml(c.seed_album||c.liked_quality||'Recommendation request')}</h2><p>${escapeHtml(c.brief)}</p></div>`;$('recommendations').innerHTML='<div class="empty">Generating set A...</div>';try{const data=await api('/recommendations',{method:'POST',body:JSON.stringify({brief:combined,seeds:c.seed_artist?[{artist:c.seed_artist}]:[],discovery_depth:c.discovery_depth?Number(c.discovery_depth):null,visibility:c.visibility||null,visual_role:c.visual_role||'preserve',n_results:3,use_lastfm:false})});currentResults=data.results||[];renderRecommendations(c,evaluator)}catch(err){$('recommendations').innerHTML=`<div class="notice bad">${escapeHtml(err.message)}</div>`}});
function scale(name,label){return `<div class="rating"><label>${label}</label><div class="scale">${[1,2,3,4,5].map(n=>`<label><input type="radio" name="${name}" value="${n}" required><span>${n}</span></label>`).join('')}</div></div>`}
function renderRecommendations(c,evaluator){$('recommendations').innerHTML=currentResults.length?currentResults.map((r,i)=>`<form class="rec" data-index="${i}"><div class="rec-title"><div><small>Set A, recommendation ${i+1}</small><h3>${escapeHtml(r.entity.artist)} · ${escapeHtml(r.entity.title)}</h3></div><strong>${r.entity.year||''}</strong></div><div class="chips">${(r.match.matched_descriptors||[]).map(x=>`<span class="chip">${escapeHtml(x)}</span>`).join('')}</div><p>${escapeHtml((r.reasons||[]).map(x=>x.claim).join(' · '))}</p><div class="ratings">${scale(`quality-${i}`,'Requested quality')}${scale(`discovery-${i}`,'Discovery value')}${scale(`connection-${i}`,'Connection clarity')}${scale(`save-${i}`,'Save or revisit')}${scale(`trust-${i}`,'Explanation trust')}</div><div class="field why"><label>Why does this work or fail?</label><textarea name="justification" required placeholder="Rate the recommendation, then explain your judgment."></textarea></div><div class="actions"><button class="btn primary" type="submit">Save judgment</button><span class="saveState"></span></div></form>`).join(''):'<div class="notice bad">No supported recommendations were returned.</div>';document.querySelectorAll('.rec').forEach(form=>{form.addEventListener('change',()=>{const scores=[...form.querySelectorAll('.scale input:checked')].map(x=>Number(x.value));if(!scores.length)return;const mean=scores.reduce((a,b)=>a+b,0)/scores.length;form.justification.placeholder=mean>=4?'What specifically made the connection convincing?':mean<=2?'What was missing, misleading, or plainly wrong?':'What worked, and what kept it from being stronger?'});form.addEventListener('submit',async e=>{e.preventDefault();const i=Number(form.dataset.index),r=currentResults[i],value=name=>Number(form.querySelector(`input[name="${name}-${i}"]:checked`)?.value||0);const body={case_id:c.id,evaluator_id:evaluator,system_arm:'platform',artist:r.entity.artist,album:r.entity.title,year:r.entity.year||'',position:i+1,requested_quality:value('quality'),discovery_value:value('discovery'),connection_clarity:value('connection'),save_revisit:value('save'),explanation_trust:value('trust'),justification:form.justification.value};try{await api('/evaluation/feedback',{method:'POST',body:JSON.stringify(body)});form.querySelector('.saveState').textContent='Saved';form.querySelector('.saveState').className='saveState saved';await refresh()}catch(err){form.querySelector('.saveState').textContent=err.message}})})}
function escapeHtml(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
$('evaluator').addEventListener('change',refresh);refresh();
</script></body></html>'''
